class CDP{
 constructor(url){this.ws=new WebSocket(url);this.id=0;this.pending=new Map();this.events=new Map();this.persistent=new Map();this.opened=new Promise((res,rej)=>{this.ws.addEventListener('open',res,{once:true});this.ws.addEventListener('error',()=>rej(new Error('CDP_OPEN')),{once:true})});this.ws.addEventListener('message',e=>{const m=JSON.parse(String(e.data));if(m.id){const p=this.pending.get(m.id);if(!p)return;this.pending.delete(m.id);m.error?p.reject(new Error(p.method+": "+m.error.message)):p.resolve(m.result)}else{const k=(m.sessionId??'')+':'+m.method;for(const fn of this.persistent.get(k)??[])fn(m.params);for(const fn of this.events.get(k)??[])fn(m.params);this.events.delete(k)}});this.ws.addEventListener('close',()=>{for(const p of this.pending.values())p.reject(new Error('CDP_CLOSED'));this.pending.clear()})}
 async send(method,params={},sessionId){await this.opened;const id=++this.id;const p=new Promise((resolve,reject)=>this.pending.set(id,{resolve,reject,method}));this.ws.send(JSON.stringify({id,method,params,...(sessionId?{sessionId}:{})}));return deadline(p,method,60000)}
 on(sessionId,method,fn){const key=sessionId+':'+method;const arr=this.persistent.get(key)??[];arr.push(fn);this.persistent.set(key,arr);return()=>this.persistent.set(key,arr.filter(x=>x!==fn));}
 once(sessionId,method){const k=sessionId+':'+method;return new Promise(resolve=>{const arr=this.events.get(k)??[];arr.push(resolve);this.events.set(k,arr)})}
}
